import { sanitizeLabel, shouldApply, type CompanionState } from "./state";

const bundleScript = document.currentScript as HTMLScriptElement | null;
const stylesheetUrl = bundleScript?.src ? new URL("./heron-companion.css", bundleScript.src).href : "/vendor/heron-companion/heron-companion.css";

export type HeronApp = "quantum" | "feed" | "learn" | "heronclient";
export type LocalCompanionEvent = {
  type: "navigation" | "refresh" | "save" | "ignore" | "review" | "lesson_complete" | "artifact_created" | "error" | "theme_changed";
  label?: string;
  domain?: string;
};

type Bootstrap = {
  state?: CompanionState;
  label?: string;
  websocketToken?: string;
  websocketUrl?: string;
  preferences?: { minimized?: boolean; hidden?: boolean; zone?: SafeZone };
};
type SafeZone = "top-left" | "top-right" | "bottom-left" | "bottom-right";

const localState: Record<LocalCompanionEvent["type"], CompanionState> = {
  navigation: "searching", refresh: "searching", save: "success", ignore: "idle",
  review: "learning", lesson_complete: "success", artifact_created: "success",
  error: "failed", theme_changed: "idle"
};
const localLabel: Record<LocalCompanionEvent["type"], string> = {
  navigation: "Searching", refresh: "Feed refreshed", save: "Saved", ignore: "Ignored",
  review: "Review recorded", lesson_complete: "Lesson complete", artifact_created: "Artifact created",
  error: "Something needs attention", theme_changed: "Theme updated"
};

class CompanionController {
  private host?: HTMLElement;
  private root?: ShadowRoot;
  private appId: HeronApp = "quantum";
  private state: CompanionState = "idle";
  private label = "Ready";
  private zone: SafeZone = "bottom-right";
  private minimized = false;
  private socket?: WebSocket;
  private reconnectTimer?: number;
  private reconnectAttempt = 0;
  private transientTimer?: number;
  private theme: Record<string, string> = {};
  private destroyed = false;
  private bootstrapUrl = "/api/v2/companion/bootstrap";
  private lastTransition = { signature: "", at: 0 };
  private themeSheet?: CSSStyleSheet;

  async init(options: { appId: HeronApp; bootstrapUrl?: string; anonymous?: boolean }): Promise<void> {
    if (document.querySelector("heron-companion[data-mounted='true']")) return;
    this.appId = options.appId;
    this.bootstrapUrl = options.bootstrapUrl || this.bootstrapUrl;
    this.zone = (localStorage.getItem(`heron-companion-zone:${this.appId}`) as SafeZone) || "bottom-right";
    this.minimized = localStorage.getItem("heron-companion-minimized") === "true";
    this.mount();
    this.render();
    try {
      const response = await fetch(this.bootstrapUrl, {
        method: "POST",
        credentials: "include",
        headers: { "content-type": "application/json", "x-heron-app": this.appId },
        body: JSON.stringify({ appId: this.appId, anonymous: Boolean(options.anonymous) })
      });
      if (!response.ok) throw new Error("bootstrap unavailable");
      const bootstrap = await response.json() as Bootstrap;
      if (bootstrap.preferences?.hidden) return this.destroy();
      this.zone = bootstrap.preferences?.zone || this.zone;
      this.minimized = bootstrap.preferences?.minimized ?? this.minimized;
      this.setState(bootstrap.state || "idle", bootstrap.label, false);
      if (bootstrap.websocketToken && bootstrap.websocketUrl) this.connect(bootstrap.websocketUrl, bootstrap.websocketToken);
    } catch {
      if (this.appId !== "quantum" || !options.anonymous) this.setState("offline", "Offline", false);
    }
  }

  emitLocal(event: LocalCompanionEvent): void {
    if (!(event.type in localState)) return;
    this.setState(localState[event.type], localLabel[event.type], true);
  }

  setTheme(theme: Record<string, string>): void {
    const allowed = ["accent", "accent2", "ink", "surface"];
    this.theme = Object.fromEntries(Object.entries(theme).filter(([key, value]) => allowed.includes(key) && /^#[0-9a-f]{3,8}$/i.test(value)));
    this.render();
  }

  minimize(): void { this.minimized = true; localStorage.setItem("heron-companion-minimized", "true"); this.render(); }
  expand(): void { this.minimized = false; localStorage.setItem("heron-companion-minimized", "false"); this.render(); }
  destroy(): void {
    this.destroyed = true;
    this.socket?.close();
    if (this.reconnectTimer) clearTimeout(this.reconnectTimer);
    this.host?.remove();
  }

  private mount(): void {
    this.host = document.createElement("heron-companion");
    this.host.dataset.mounted = "true";
    this.host.dataset.app = this.appId;
    this.root = this.host.attachShadow({ mode: "open" });
    document.body.append(this.host);
  }

  private setState(state: CompanionState, label?: string, transient = false): void {
    if (!shouldApply(this.state, state) && transient) return;
    const nextLabel = sanitizeLabel(label, state);
    const signature = `${state}:${nextLabel}`;
    if (this.lastTransition.signature === signature && Date.now() - this.lastTransition.at < 500) return;
    this.lastTransition = { signature, at: Date.now() };
    this.state = state;
    this.label = nextLabel;
    this.render();
    window.dispatchEvent(new CustomEvent("heron:companion-state", { detail: { appId: this.appId, state } }));
    if (this.transientTimer) clearTimeout(this.transientTimer);
    if (transient && !["failed", "awaiting_approval"].includes(state)) {
      this.transientTimer = window.setTimeout(() => this.setState(this.socket?.readyState === WebSocket.OPEN ? "idle" : "offline", undefined, false), 2200);
    }
  }

  private connect(url: string, token: string): void {
    if (this.destroyed) return;
    const protocol = `heron-companion.${token}`;
    this.socket = new WebSocket(url, protocol);
    this.socket.onopen = () => { this.reconnectAttempt = 0; if (this.state === "offline") this.setState("idle"); };
    this.socket.onmessage = (message) => {
      try {
        const event = JSON.parse(String(message.data));
        const states: CompanionState[] = ["idle", "listening", "thinking", "searching", "learning", "building", "awaiting_approval", "success", "failed", "offline"];
        if (states.includes(event.state)) this.setState(event.state, event.label, false);
      } catch { /* Ignore malformed or non-public events. */ }
    };
    this.socket.onclose = () => {
      this.setState("offline", "Offline", false);
      const delay = Math.min(30000, 750 * 2 ** this.reconnectAttempt++) + Math.random() * 300;
      this.reconnectTimer = window.setTimeout(() => this.rebootstrap(), delay);
    };
  }

  private async rebootstrap(): Promise<void> {
    if (this.destroyed) return;
    try {
      const response = await fetch(this.bootstrapUrl, { method: "POST", credentials: "include", headers: { "content-type": "application/json", "x-heron-app": this.appId }, body: JSON.stringify({ appId: this.appId }) });
      if (!response.ok) throw new Error();
      const value = await response.json() as Bootstrap;
      if (value.websocketToken && value.websocketUrl) this.connect(value.websocketUrl, value.websocketToken);
    } catch {
      const delay = Math.min(30000, 750 * 2 ** this.reconnectAttempt++);
      this.reconnectTimer = window.setTimeout(() => this.rebootstrap(), delay);
    }
  }

  private move(): void {
    const zones: SafeZone[] = ["bottom-right", "bottom-left", "top-left", "top-right"];
    this.zone = zones[(zones.indexOf(this.zone) + 1) % zones.length];
    localStorage.setItem(`heron-companion-zone:${this.appId}`, this.zone);
    this.render();
  }

  private render(): void {
    if (!this.root) return;
    const accent = this.theme.accent || ({ quantum: "#b7f34a", feed: "#52d4ff", learn: "#bd8cff", heronclient: "#ff9f43" })[this.appId];
    const title = ({ quantum: "Quantum guide", feed: "Signal scout", learn: "Learning heron", heronclient: "Heron agent" })[this.appId];
    if ("adoptedStyleSheets" in this.root && "replaceSync" in CSSStyleSheet.prototype) {
      this.themeSheet ||= new CSSStyleSheet();
      this.themeSheet.replaceSync(`:host{--heron-accent:${accent};--heron-accent-2:${this.theme.accent2 || "#58d7ff"};--heron-ink:${this.theme.ink || "#10151b"};--heron-surface:${this.theme.surface || "#f6f7ed"}}`);
      this.root.adoptedStyleSheets = [this.themeSheet];
    }
    this.root.innerHTML = `<link rel="stylesheet" href="${stylesheetUrl}">
      <section class="companion ${this.zone} ${this.minimized ? "minimized" : ""}" data-state="${this.state}" data-app="${this.appId}" aria-label="${title}: ${this.label}">
        <button class="mascot" type="button" aria-label="${this.minimized ? "Expand" : "Open"} ${title}">
          <span class="orbit" aria-hidden="true"></span>
          <svg viewBox="0 0 120 120" role="img" aria-hidden="true"><path class="wing" d="M52 62c-24 4-32 20-37 36 19-9 32-12 48-3"/><path class="body" d="M66 102c-18-10-21-35-8-49 7-7 13-12 12-25 13 10 12 23 4 34-8 12-5 25 8 40z"/><path class="neck" d="M70 31c7-17 18-19 29-12-10 1-13 6-15 14"/><circle class="eye" cx="88" cy="21" r="2.5"/><path class="beak" d="M96 21l20 5-19 3z"/><path class="leg" d="M66 96v19m13-16 5 16"/></svg>
        </button>
        <div class="bubble" role="status" aria-live="polite"><strong>${title}</strong><span>${this.label}</span><div class="actions"><button data-action="move" type="button">Move</button><button data-action="minimize" type="button">${this.minimized ? "Expand" : "Minimize"}</button></div></div>
      </section>`;
    this.root.querySelector<HTMLButtonElement>(".mascot")?.addEventListener("click", () => this.minimized ? this.expand() : this.root?.querySelector(".companion")?.classList.toggle("open"));
    this.root.querySelector<HTMLButtonElement>("[data-action='move']")?.addEventListener("click", () => this.move());
    this.root.querySelector<HTMLButtonElement>("[data-action='minimize']")?.addEventListener("click", () => this.minimized ? this.expand() : this.minimize());
  }
}

export const HeronCompanion = new CompanionController();
declare global { interface Window { HeronCompanion: CompanionController; } }
window.HeronCompanion = HeronCompanion;

const autoScript = bundleScript;
function autoInit(): void {
  const script = autoScript;
  const appId = script?.dataset.heronApp as HeronApp | undefined;
  if (script?.dataset.heronCompanion !== undefined && appId) {
    void HeronCompanion.init({ appId, bootstrapUrl: script.dataset.bootstrapUrl, anonymous: script.dataset.anonymous === "true" });
  }
}
if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", autoInit, { once: true }); else autoInit();
